'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const norm=s=>String(s).normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const months=['January','February','March','April','May','June','July','August','September','October','November','December'];
let db, results=[], currentPage=1, view='explore', layout='grid', current=null;
function localGet(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}}
let saved=new Set(localGet('metro-saved',[])), notes=localGet('metro-notes',{});
function persist(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true}catch{toast('Browser storage is unavailable. Export a copy to keep your work.');return false}}
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',3000)}
function terms(){let q=$('#search').value.trim();if($('#match').value==='exact')return q?[norm(q.replace(/^"|"$/g,''))]:[];return (q.match(/"[^"]+"|\S+/g)||[]).map(s=>norm(s.replace(/^"|"$/g,'')))}
function selected(p,ignoreCategory=false){return(!$('#year').value||p.year==$('#year').value)&&(!$('#month').value||p.monthNumber==$('#month').value)&&(ignoreCategory||!$('#category').value||p.categories.includes($('#category').value))&&(!$('#brandFilter').value||p.brands.includes($('#brandFilter').value))}
function matches(p,ts){return !ts.length||($('#match').value==='any'?ts.some(t=>p._search.includes(t)):ts.every(t=>p._search.includes(t)))}
function highlight(s){let parts=terms().filter(Boolean).sort((a,b)=>b.length-a.length);if(!parts.length)return esc(s);let re=new RegExp('('+parts.map(t=>t.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')).join('|')+')','gi');return esc(s).replace(re,'<mark>$1</mark>')}
function excerpt(p){const text=p.text.replace(/\s+/g,' ');let ts=terms(), index=ts.length?norm(text).indexOf(ts[0]):-1;let start=index>70?index-55:0;return(start?'…':'')+text.slice(start,start+240)+(text.length>start+240?'…':'')}
function setView(v){view=v;currentPage=1;$$('.nav').forEach(b=>b.classList.toggle('active',b.dataset.view===view));let names={explore:['Discover. Connect. Remember.','Find the news, people and achievements behind our journey.'],issues:['Every edition. One library.','Browse the original newsletters, month by month.'],saved:['Keep the moments that matter.','Your personal collection of news pages, saved in this browser.'],insights:['Our journey, at a glance.','Explore the coverage and themes in the Metropolitan archive.']};$('#viewTitle').textContent=names[v][0];$('#viewSubtitle').textContent=names[v][1];render()}
function updateUrl(){let u=new URL(location.href);u.search='';for(let key of ['search','year','month','category','brandFilter','match'])if($('#'+key).value&&(key!=='match'||$('#match').value!=='all'))u.searchParams.set(key,$('#'+key).value);if(view!=='explore')u.searchParams.set('view',view);if(current)u.searchParams.set('page',current.id);history.replaceState(null,'',u)}
function render(){if(!db)return;const ts=terms();let base=db.pages.filter(p=>selected(p,true)&&matches(p,ts)&&(view!=='saved'||saved.has(p.id)));results=base.filter(p=>!$('#category').value||p.categories.includes($('#category').value));const sort=$('#sort').value;results.sort((a,b)=>sort==='oldest'?a.id.localeCompare(b.id):sort==='relevance'&&ts.length?(score(b,ts)-score(a,ts)||b.id.localeCompare(a.id)):b.id.localeCompare(a.id));
$('#savedCount').textContent=saved.size;$('#stats').innerHTML=[['▤',db.issues.length,'Newsletter issues','issues'],['⌕',db.pages.length,'Searchable pages','explore'],['▥',new Set(db.pages.map(p=>p.year)).size,'Years of stories','insights'],['☆',saved.size,'Saved pages','saved']].map(([icon,n,label,v])=>`<button class="stat" data-stat="${v}"><span class="stat-icon">${icon}</span><span><strong>${n}</strong><small>${label}</small></span></button>`).join('');
$('#categoryChips').innerHTML=[`<button class="chip ${!$('#category').value?'active':''}" data-category="">All news <b>${base.length}</b></button>`,...db.categories.map(c=>{let n=base.filter(p=>p.categories.includes(c)).length;return n?`<button class="chip ${$('#category').value===c?'active':''}" data-category="${esc(c)}">${esc(c)} <b>${n}</b></button>`:''})].join('');
$('#pagination').innerHTML='';$('#export').disabled=!results.length;$('#layout').hidden=view==='insights';
if(view==='issues')renderIssues();else if(view==='insights')renderInsights();else renderPages();updateUrl()}
function score(p,ts){return ts.reduce((n,t)=>n+(norm(p.title).includes(t)?20:0)+(p._search.split(t).length-1),0)}
function renderPages(){const size=12;let max=Math.max(1,Math.ceil(results.length/size));currentPage=Math.min(currentPage,max);let start=(currentPage-1)*size;$('#resultsTitle').textContent=view==='saved'?'Your saved news pages':terms().length?'Search results':'News pages';$('#resultCount').textContent=`${results.length} matching pages · ${new Set(results.map(p=>p.issue)).size} newsletters${results.length?` · Showing ${start+1}–${Math.min(start+size,results.length)}`:''}`;$('#content').className=layout;
$('#content').innerHTML=results.length?results.slice(start,start+size).map(card).join(''):`<div class="empty"><span style="font-size:36px">${view==='saved'?'☆':'⌕'}</span><h3>${view==='saved'&&!saved.size?'Your collection starts here.':'No matching pages found.'}</h3><p>${view==='saved'&&!saved.size?'Use the star on any news page to save it.':'Try fewer keywords, “Any keyword”, or reset your filters.'}</p><button class="outline" data-reset>Explore all news</button></div>`;
if(max>1)$('#pagination').innerHTML=`<button data-page="${currentPage-1}" ${currentPage===1?'disabled':''}>← Previous</button><span>Page ${currentPage} of ${max}</span><button data-page="${currentPage+1}" ${currentPage===max?'disabled':''}>Next →</button>`}
function card(p){return `<article class="card"><div class="card-media"><button class="card-image" data-open="${p.id}" aria-label="Read ${esc(p.title)}"><img src="thumbs/${p.id}.webp" alt="${esc(p.month)} ${p.year} newsletter, page ${p.page}" loading="lazy"><span class="page-label">PAGE ${p.page} · NEWSLETTER</span></button><button class="bookmark ${saved.has(p.id)?'saved':''}" data-save="${p.id}" aria-label="${saved.has(p.id)?'Remove from':'Add to'} saved collection" aria-pressed="${saved.has(p.id)}">${saved.has(p.id)?'★':'☆'}</button></div><div class="card-body"><div class="card-meta"><span>${p.month} ${p.year}</span><span>${p.ocr?'OCR transcript':'Original text'}</span></div><h3><button class="titlebutton" data-open="${p.id}">${highlight(p.title)}</button></h3><p class="excerpt">${highlight(excerpt(p))}</p><div class="tags">${p.categories.slice(0,2).map(t=>`<span class="tag">${esc(t)}</span>`).join('')}${p.categories.length>2?`<span class="tag">+${p.categories.length-2}</span>`:''}</div><div class="card-footer"><span>METRO NEWS · ${p.year}</span><button class="readbtn" data-open="${p.id}">Read page →</button></div></div></article>`}
function renderIssues(){let ids=new Set(results.map(p=>p.issue)), issues=db.issues.filter(i=>ids.has(i.id));issues.sort((a,b)=>$('#sort').value==='oldest'?a.id.localeCompare(b.id):b.id.localeCompare(a.id));$('#resultsTitle').textContent='Newsletter library';$('#resultCount').textContent=`${issues.length} newsletters · ${results.length} matching pages`;$('#content').className=layout;$('#content').innerHTML=issues.length?issues.map(i=>`<article class="card issue-card"><div class="card-media"><button class="card-image" data-issue="${i.id}" aria-label="Browse ${i.month} ${i.year}"><img loading="lazy" src="${i.cover}" alt="${i.month} ${i.year} cover"><span class="page-label">${i.pages} PAGES · PDF</span></button></div><div class="card-body"><div class="card-meta">METRO NEWS</div><h3>${i.month} ${i.year}</h3><p class="muted">${results.filter(p=>p.issue===i.id).length} pages match your current filters</p><div class="card-footer"><a href="${i.pdf}" target="_blank" rel="noopener">Open PDF ↗</a><button class="readbtn" data-issue="${i.id}">Browse pages →</button></div></div></article>`).join(''):'<div class="empty"><h3>No matching newsletters</h3><p>Try resetting the filters.</p></div>'}
function renderInsights(){let counts=db.categories.map(c=>[c,results.filter(p=>p.categories.includes(c)).length]).filter(x=>x[1]).sort((a,b)=>b[1]-a[1]);let max=Math.max(...counts.map(x=>x[1]),1);$('#resultsTitle').textContent='Archive overview';$('#resultCount').textContent=`Based on ${results.length} pages matching your current filters`;$('#content').className='';$('#content').innerHTML=`<section class="insight-panel"><h3>Topics across the archive</h3><p class="muted">Automatically suggested page categories. A page can cover several topics, so counts overlap. Select a topic to explore its pages.</p>${counts.map(([c,n])=>`<div class="bar-row"><button data-topic="${esc(c)}">${esc(c)}</button><div class="bar-track"><span style="width:${n/max*100}%"></span></div><b>${n}</b></div>`).join('')||'<p>No pages match these filters.</p>'}</section>${[2024,2023].map(y=>`<section class="insight-panel"><h3>${y} newsletter coverage</h3><p class="muted">All 12 supplied monthly editions. Select a month to explore the issue.</p><div class="coverage">${months.map((m,k)=>{let i=db.issues.find(i=>i.year===y&&i.monthNumber===k+1);return `<button data-issue="${i.id}">${m.slice(0,3)}<b>${i.pages} pages</b></button>`}).join('')}</div></section>`).join('')}<section class="insight-panel"><h3>Ready for the next chapter</h3><p>2025 and 2026 can be added when you supply those newsletters. Search, filters and source references will expand with the archive.</p><p class="muted">No 2025 or 2026 content is included in this edition.</p></section>`}
function reset(){for(let x of ['search','year','month','category','brandFilter'])$('#'+x).value='';$('#match').value='all';currentPage=1;render()}
function save(id){if(saved.has(id))saved.delete(id);else saved.add(id);persist('metro-saved',[...saved]);render();if(current)updateReaderSave()}
function updateReaderSave(){$('#saveReader').textContent=saved.has(current.id)?'★ Saved to collection':'☆ Save page';$('#saveReader').setAttribute('aria-pressed',saved.has(current.id))}
function openPage(id){let p=db.pages.find(p=>p.id===id);if(!p)return;current=p;$('#readerSource').textContent=`METRO NEWS · ${p.month} ${p.year} · PAGE ${p.page}`;$('#readerTitle').textContent=p.title;$('#readerPage').textContent=`${p.page} / ${db.issues.find(i=>i.id===p.issue).pages}`;$('#pageImage').src=`pages/${id}.webp`;$('#pageImage').alt=`Original ${p.month} ${p.year} newsletter page ${p.page}`;$('#openPdf').href=`${p.pdf}#page=${p.page}`;$('#downloadPdf').href=p.pdf;$('#downloadPdf').download=`Metropolitan-Newsletter-${p.issue}.pdf`;$('#readerTags').innerHTML=p.categories.map(c=>`<span class="tag">${esc(c)}</span>`).join('');$('#ocrNote').textContent=p.ocr?'Text recognised from a scanned page. OCR can contain errors; check the original page for important details.':'Extracted from the original PDF. Page reading order and spacing can vary; check the original page for important details.';$('#transcript').innerHTML=highlight(p.text||'This is a visual page. Please view the original newsletter image or PDF.');$('#note').value=notes[id]||'';$('#noteStatus').textContent='';$('#prevPage').disabled=p.page===1;$('#nextPage').disabled=!db.pages.some(x=>x.issue===p.issue&&x.page===p.page+1);updateReaderSave();const related=db.pages.filter(x=>x.id!==p.id).map(x=>({p:x,s:x.categories.filter(c=>p.categories.includes(c)).length+x.brands.filter(b=>p.brands.includes(b)).length*2})).filter(x=>x.s>0).sort((a,b)=>b.s-a.s||b.p.id.localeCompare(a.p.id)).slice(0,3);$('#related').innerHTML='<h3>Related pages</h3>'+related.map(({p})=>`<button data-open="${p.id}">${esc(p.title)}<br><span class="muted">${p.month} ${p.year} · Page ${p.page}</span></button>`).join('');if(!$('#reader').open)$('#reader').showModal();$('.reader-body').scrollTop=0;updateUrl()}
function browseIssue(id){let i=db.issues.find(x=>x.id===id);reset();$('#year').value=i.year;$('#month').value=i.monthNumber;setView('explore');$('.workspace').scrollIntoView({behavior:'smooth'})}
function exportResults(){let rows=[['Issue year','Issue month','Page','Title','Categories','Brands / organisations','Source PDF','Text source','Transcript','Personal note'],...results.map(p=>[p.year,p.month,p.page,p.title,p.categories.join('; '),p.brands.join('; '),new URL(p.pdf,location.href).href+'#page='+p.page,p.ocr?'OCR':'PDF text',p.text,notes[p.id]||''])];let csv='\uFEFF'+rows.map(row=>row.map(c=>'"'+String(c??'').replace(/^[=+@-]/,"'$&").replace(/"/g,'""')+'"').join(',')).join('\r\n');let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download='Metropolitan-news-search-results.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),2000);toast(`Exported ${results.length} page references and transcripts`)}
document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;if(b.dataset.view)setView(b.dataset.view);if(b.dataset.stat){reset();setView(b.dataset.stat)}if(b.dataset.category!==undefined){$('#category').value=b.dataset.category;currentPage=1;render()}if(b.dataset.topic){$('#category').value=b.dataset.topic;setView('explore')}if(b.dataset.open)openPage(b.dataset.open);if(b.dataset.save)save(b.dataset.save);if(b.dataset.issue)browseIssue(b.dataset.issue);if(b.dataset.page){currentPage=Number(b.dataset.page);render();$('.results-heading').scrollIntoView({behavior:'smooth'})}if(b.dataset.query){$('#search').value=b.dataset.query;$('#sort').value='relevance';setView('explore')}if(b.hasAttribute('data-reset')){reset();setView('explore')}});
$('#searchBtn').onclick=()=>{currentPage=1;if(view==='insights')setView('explore');else render()};let debounce;$('#search').oninput=()=>{clearTimeout(debounce);debounce=setTimeout(()=>{currentPage=1;if(terms().length)$('#sort').value='relevance';render()},250)};$('#search').onkeydown=e=>{if(e.key==='Enter'){$('#searchBtn').click();e.preventDefault()}};for(let id of ['year','month','category','brandFilter','match','sort'])$('#'+id).onchange=()=>{currentPage=1;render()};$('#reset').onclick=reset;$('#export').onclick=exportResults;$('#layout').onclick=()=>{layout=layout==='grid'?'list':'grid';$('#layout').textContent=layout==='grid'?'☷':'▦';$('#layout').setAttribute('aria-label',`Switch to ${layout==='grid'?'list':'grid'} view`);render()};$('#closeReader').onclick=()=>$('#reader').close();$('#reader').addEventListener('close',()=>{current=null;updateUrl()});$('#saveReader').onclick=()=>save(current.id);$('#prevPage').onclick=()=>{let p=db.pages.find(p=>p.issue===current.issue&&p.page===current.page-1);if(p)openPage(p.id)};$('#nextPage').onclick=()=>{let p=db.pages.find(p=>p.issue===current.issue&&p.page===current.page+1);if(p)openPage(p.id)};$('#note').oninput=()=>{notes[current.id]=$('#note').value;$('#noteStatus').textContent=persist('metro-notes',notes)?'Note saved':''};$('#copySource').onclick=async()=>{let text=`Metropolitan Technologies — Metro News, ${current.month} ${current.year}, page ${current.page}: ${current.title}. ${new URL(current.pdf,location.href).href}#page=${current.page}`;try{await navigator.clipboard.writeText(text);toast('Source reference copied')}catch{toast('Copy is unavailable in this browser. Use the source PDF link.')}};$('#aboutBtn').onclick=$('#sourceNote').onclick=()=>$('#about').showModal();$('#closeAbout').onclick=()=>$('#about').close();document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!$('#reader').open){e.preventDefault();$('#search').focus()}});
(async()=>{try{let r=await fetch('data.json');if(!r.ok)throw Error('Archive data could not be loaded');db=await r.json();db.pages.forEach(p=>p._search=norm([p.title,p.text,p.year,p.month,...p.brands].join(' ')));$('#month').innerHTML+=months.map((m,i)=>`<option value="${i+1}">${m}</option>`).join('');$('#category').innerHTML+=db.categories.map(c=>`<option>${esc(c)}</option>`).join('');$('#brandFilter').innerHTML+=[...new Set(db.pages.flatMap(p=>p.brands))].sort().map(b=>`<option>${esc(b)}</option>`).join('');let u=new URL(location.href),page=u.searchParams.get('page');for(let key of ['search','year','month','category','brandFilter','match'])if(u.searchParams.has(key))$('#'+key).value=u.searchParams.get(key);if(terms().length)$('#sort').value='relevance';setView(['explore','issues','saved','insights'].includes(u.searchParams.get('view'))?u.searchParams.get('view'):'explore');if(page)openPage(page)}catch(e){$('#content').innerHTML=`<div class="empty"><h3>The archive could not load.</h3><p>Please refresh the page to try again.</p></div>`;$('#resultCount').textContent='Archive unavailable';console.error(e)}})();
